export function createOfflineQueue({
  storage,
  send,
  key = "queue:v1",
  maxAttempts = 5,
}) {
  let pending = [];

  try {
    const stored = storage.getItem(key);
    if (stored !== null) {
      const parsed = JSON.parse(stored);
      if (Array.isArray(parsed)) {
        pending = parsed;
      }
    }
  } catch {
    pending = [];
  }

  let inFlight = null;
  let runningFlush = null;

  function persist() {
    storage.setItem(key, JSON.stringify(pending));
  }

  function enqueue({ id, type, payload, dedupeKey }) {
    if (pending.some((item) => item.id === id)) {
      return;
    }

    const match =
      dedupeKey === undefined
        ? undefined
        : pending.find(
            (item) => item !== inFlight && item.dedupeKey === dedupeKey,
          );

    if (match) {
      match.type = type;
      match.payload = payload;
      match.attempts = 0;
    } else {
      pending.push({ id, type, payload, dedupeKey, attempts: 0 });
    }

    persist();
  }

  async function drain(resolve, reject) {
    const sent = [];
    const failed = [];

    try {
      while (pending.length > 0) {
        const item = pending[0];
        inFlight = item;

        let outcome = "retryable";

        try {
          const response = await send({
            id: item.id,
            type: item.type,
            payload: item.payload,
          });

          const ok = response == null ? undefined : response.ok;

          if (ok === true) {
            outcome = "success";
          } else if (ok === false && response.retryable === false) {
            outcome = "rejected";
          }
        } catch {
          // Rejections and synchronous send errors are retryable.
        }

        inFlight = null;

        if (outcome === "retryable") {
          item.attempts += 1;
          persist();

          if (item.attempts >= maxAttempts) {
            pending.shift();
            persist();
            failed.push({ id: item.id, reason: "max-attempts" });
          }

          break;
        }

        pending.shift();
        persist();

        if (outcome === "success") {
          sent.push(item.id);
        } else {
          failed.push({ id: item.id, reason: "rejected" });
        }
      }

      resolve({ sent, failed, remaining: pending.length });
    } catch (error) {
      reject(error);
    } finally {
      inFlight = null;
      runningFlush = null;
    }
  }

  function flush() {
    if (runningFlush !== null) {
      return runningFlush;
    }

    let resolveRun;
    let rejectRun;

    const promise = new Promise((resolve, reject) => {
      resolveRun = resolve;
      rejectRun = reject;
    });

    // Register the promise before send can synchronously re-enter flush.
    runningFlush = promise;
    drain(resolveRun, rejectRun);

    return promise;
  }

  return {
    enqueue,
    flush,

    size() {
      return pending.length;
    },

    peek() {
      return pending.map((item) => ({
        id: item.id,
        type: item.type,
        payload: item.payload,
        dedupeKey: item.dedupeKey,
        attempts: item.attempts,
      }));
    },
  };
}
